:root {
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,body,#root {
  margin: 0;
  min-height: 100%;
  background: #020617;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #020617;
  color: #e5e7eb;
}

.card {
  width: min(100%,680px);
  min-width: 0;
  display: grid;
  gap: 14px;
  padding: 20px;
  border: 1px solid #1f2937;
  border-radius: 16px;
  background: #0b1020;
}

.header {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.header h1 {
  margin: 0;
  font-size: 21px;
}

.subtitle,.hint,.invite-limit,.invite-status {
  margin: 0;
  overflow-wrap: anywhere;
}

.subtitle {
  color: #9ca3af;
  font-size: 14px;
  line-height: 1.5;
}

.combobox {
  position: relative;
  min-width: 0;
  display: grid;
  gap: 7px;
}

.field-label {
  font-size: 13px;
  font-weight: 700;
  color: #cbd5e1;
}

.chip-field {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 10px;
  border: 1px solid #374151;
  border-radius: 12px;
  background: #0a0f1e;
}

.chip-field:focus-within {
  border-color: #a3e635;
  box-shadow: 0 0 0 2px rgba(163,230,53,.16);
}

.chip {
  max-width: 100%;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 9px;
  border: 1px solid #334155;
  border-radius: 999px;
  background: #172036;
  font-size: 13px;
}

.chip-label {
  min-width: 0;
  overflow-wrap: anywhere;
}

.chip-remove {
  flex: 0 0 auto;
  border: 0;
  background: transparent;
  color: #cbd5e1;
  cursor: pointer;
  font-size: 17px;
  line-height: 1;
  padding: 0;
}

.chip-remove:hover {
  color: #fff;
}

.chip-input {
  flex: 1 1 190px;
  min-width: 140px;
  max-width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #f8fafc;
  font: inherit;
  font-size: 14px;
  padding: 5px 2px;
}

.chip-input::placeholder {
  color: #64748b;
}

.chip-input:disabled {
  cursor: not-allowed;
  color: #94a3b8;
}

.chip-remove:focus-visible,.chip-input:focus-visible,.suggestion:focus-visible {
  outline: 3px solid #facc15;
  outline-offset: 2px;
}

.suggestions {
  position: absolute;
  z-index: 10;
  top: 100%;
  left: 0;
  right: 0;
  max-height: 260px;
  overflow: auto;
  margin: 7px 0 0;
  padding: 0;
  border: 1px solid #334155;
  border-radius: 12px;
  background: #0a0f1e;
  list-style: none;
  box-shadow: 0 16px 32px rgba(0,0,0,.35);
}

.suggestion {
  min-width: 0;
  display: grid;
  gap: 3px;
  padding: 10px 12px;
  border-bottom: 1px solid rgba(51,65,85,.6);
  cursor: pointer;
  overflow-wrap: anywhere;
}

.suggestion:last-child {
  border-bottom: 0;
}

.suggestion:hover,.suggestion.active {
  background: rgba(163,230,53,.13);
}

.suggestion strong {
  font-size: 14px;
}

.suggestion span {
  color: #94a3b8;
  font-size: 12px;
}

.hint,.invite-limit,.invite-status {
  font-size: 12px;
  line-height: 1.5;
}

.hint {
  color: #94a3b8;
}

.invite-limit {
  color: #cbd5e1;
  font-weight: 650;
}

.invite-status {
  min-height: 18px;
  color: #bef264;
}

@media (max-width:480px) {
  .page {
    place-items: start center;
    padding: 12px;
  }

  .card {
    padding: 15px;
  }

  .chip-field {
    align-items: stretch;
  }

  .chip-input {
    flex-basis: 100%;
    min-width: 0;
  }

  .suggestions {
    max-height: 220px;
  }

  .chip {
    max-width: 100%;
  }
}
